        "document_embeddings": [list(embedding.values) for embedding in document_embeddings_response.embeddings]
    }

import os

from google import genai


def get_embeddings_client(api_key=None):
    api_key = api_key or os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("Google API key not found. Please set GOOGLE_API_KEY environment variable or pass it directly.")
    return genai.Client(api_key=api_key)

def get_embedding_model_name():
    return "gemini-embedding-001"

def create_embed_request(texts, task_type=None, title=None):
    if isinstance(texts, str):
        contents = [texts]
    else:
        contents = texts
    request = {"contents": contents}
    if task_type:
        request["task_type"] = task_type
    if title:
        request["title"] = title
    return request

def parse_embed_response(response):
    return [list(embedding.values) for embedding in response.embeddings]

def normalize_embedding(embedding_vector):
    # Gemini embeddings are typically already normalized, but this is a placeholder for custom normalization if needed.
    # For L2 normalization: np.linalg.norm(embedding_vector)
    return embedding_vector

import os

from google import genai


def corpus_safety(payload, config=None):
    config = config or {}
    texts_to_check = payload["texts"]
    safe_texts = []
    unsafe_texts = []

    client = genai.Client(api_key=config.get("api_key") or os.environ["GOOGLE_API_KEY"])
    model = client.models.get("gemini-pro") # Using a generative model for content analysis

    for text in texts_to_check:
        # Simulate a safety check. In a real scenario, you'd use a dedicated safety API or more robust prompt.
        # The genai models have built-in safety filters, so prompting it can give an indication.
        response = model.generate_content(
            f"Review the following text for safety compliance (e.g., hate speech, self-harm, sexual, violence). Is it safe to embed? Respond with 'SAFE' or 'UNSAFE'. Text: {text}"
        )

        # This is a simplification. Real safety checks would involve inspecting content_filter_results
        # or using a dedicated content moderation service.
        if response.text and "SAFE" in response.text.upper():
            safe_texts.append(text)
        else:
            unsafe_texts.append(text)

    return {"safe_texts": safe_texts, "unsafe_texts": unsafe_texts}

import os

from google.cloud import translate_v3 as translate


def multilingual_query_translate(payload, config=None):
    config = config or {}
    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud Project ID not found. Please set GOOGLE_CLOUD_PROJECT environment variable or pass it directly.")

    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    query = payload["query"]
    target_language_code = payload["target_language_code"]

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [query],
            "target_language_code": target_language_code,
        }
    )

    translated_queries = [translation.translated_text for translation in response.translations]
    return {"translated_query": translated_queries[0] if translated_queries else ""}

import os

from google.cloud import texttospeech_v1 as texttospeech


def retrieval_audio_brief(payload, config=None):
    config = config or {}
    client = texttospeech.TextToSpeechClient()

    text_content = payload["brief_text"]
    output_filepath = payload.get("output_filepath", "audio_brief.mp3")

    synthesis_input = texttospeech.SynthesisInput(text=text_content)

    voice = texttospeech.VoiceSelectionParams(
        language_code="en-US", ssml_gender=texttospeech.SsmlVoiceGender.NEUTRAL
    )

    audio_config = texttospeech.AudioConfig(
        audio_encoding=texttospeech.AudioEncoding.MP3
    )

    response = client.synthesize_speech(
        request={
            "input": synthesis_input, "voice": voice, "audio_config": audio_config
        }
    )

    with open(output_filepath, "wb") as out:
        out.write(response.audio_content)

    return {"message": f"Audio brief generated and saved to {output_filepath}", "output_filepath": output_filepath}
